namespace { constexpr int roleKind=Qt::UserRole,roleId=Qt::UserRole+1;
QDoubleSpinBox* number(const char* name,double min=0,double max=1e9){auto* e=new QDoubleSpinBox;e->setObjectName(name);e->setDecimals(3);e->setRange(min,max);return e;}
QWidget* page(QFormLayout* form){auto* w=new QWidget;auto* l=new QVBoxLayout(w);l->addLayout(form);l->addStretch();return w;}}

InfraMainWindow::InfraMainWindow(QWidget* parent):QMainWindow(parent){setObjectName("infraMainWindow");resize(1440,900);buildUi();buildMenus();newDocument();dirty_=false;document_.clearHistory();const QSettings s;restoreGeometry(s.value("infra/geometry").toByteArray());restoreState(s.value("infra/state").toByteArray());}

void InfraMainWindow::buildUi(){
    viewport_=new InfraViewport(this);setCentralWidget(viewport_);
    auto* bd=new QDockWidget(tr("Infrastructure Model"),this);bd->setObjectName("infraBrowserDock");tree_=new QTreeWidget;tree_->setObjectName("infraProjectTree");tree_->setHeaderLabels({tr("Feature"),tr("Data")});tree_->header()->setSectionResizeMode(0,QHeaderView::Stretch);bd->setWidget(tree_);addDockWidget(Qt::LeftDockWidgetArea,bd);
    auto* pd=new QDockWidget(tr("Feature Properties"),this);pd->setObjectName("infraPropertiesDock");auto* root=new QWidget;auto* layout=new QVBoxLayout(root);summary_=new QLabel(tr("No selection"));summary_->setWordWrap(true);layout->addWidget(summary_);stack_=new QStackedWidget;stack_->addWidget(new QLabel(tr("Select terrain, a component road, bridge, or building.")));
    auto* rf=new QFormLayout;roadName_=new QLineEdit;roadName_->setObjectName("roadNameEditor");roadLanes_=new QSpinBox;roadLanes_->setRange(1,20);roadWidth_=number("roadWidthEditor",0.1,30);roadSpeed_=number("roadSpeedEditor",1,400);roadInfo_=new QLabel;roadInfo_->setWordWrap(true);analysisInterval_=number("earthworkIntervalEditor",0.1,10000);analysisInterval_->setValue(10);earthwork_=new QLabel(tr("Run corridor analysis against the active DEM."));earthwork_->setWordWrap(true);auto* analyze=new QPushButton(tr("Analyze Corridor Earthworks"));analyze->setObjectName("earthworkButton");connect(analyze,&QPushButton::clicked,this,&InfraMainWindow::analyzeEarthworks);rf->addRow(tr("Name"),roadName_);rf->addRow(tr("Lanes"),roadLanes_);rf->addRow(tr("Lane width (m)"),roadWidth_);rf->addRow(tr("Design speed (km/h)"),roadSpeed_);rf->addRow(tr("Geometry"),roadInfo_);rf->addRow(tr("Station interval (m)"),analysisInterval_);rf->addRow(QString(),analyze);rf->addRow(tr("Earthworks"),earthwork_);stack_->addWidget(page(rf));
    auto* bf=new QFormLayout;bridgeName_=new QLineEdit;bridgeName_->setObjectName("bridgeNameEditor");bridgeStart_=number("bridgeStartEditor");bridgeEnd_=number("bridgeEndEditor");bridgePiers_=new QSpinBox;bridgePiers_->setRange(0,1000);bridgeThickness_=number("bridgeThicknessEditor",0.1,100);bf->addRow(tr("Name"),bridgeName_);bf->addRow(tr("Start station"),bridgeStart_);bf->addRow(tr("End station"),bridgeEnd_);bf->addRow(tr("Pier count"),bridgePiers_);bf->addRow(tr("Deck thickness"),bridgeThickness_);stack_->addWidget(page(bf));
    auto* uf=new QFormLayout;buildingName_=new QLineEdit;buildingName_->setObjectName("buildingNameEditor");buildingUsage_=new QComboBox;buildingUsage_->addItems({tr("Residential"),tr("Commercial"),tr("Civic"),tr("Industrial")});buildingHeight_=number("buildingHeightEditor",0.1,1000);buildingInfo_=new QLabel;buildingInfo_->setWordWrap(true);uf->addRow(tr("Name"),buildingName_);uf->addRow(tr("Usage"),buildingUsage_);uf->addRow(tr("Roof height"),buildingHeight_);uf->addRow(tr("Draped footprint"),buildingInfo_);stack_->addWidget(page(uf));
    auto* tf=new QFormLayout;projectName_=new QLineEdit;projectName_->setObjectName("projectNameEditor");crs_=new QLineEdit;crs_->setObjectName("crsEditor");terrainInfo_=new QLabel;terrainInfo_->setWordWrap(true);tf->addRow(tr("Project"),projectName_);tf->addRow(tr("Coordinate system"),crs_);tf->addRow(tr("DEM"),terrainInfo_);stack_->addWidget(page(tf));layout->addWidget(stack_,1);auto* apply=new QPushButton(tr("Apply Properties"));apply->setObjectName("applyInfraPropertiesButton");connect(apply,&QPushButton::clicked,this,&InfraMainWindow::applyProperties);layout->addWidget(apply);pd->setWidget(root);addDockWidget(Qt::RightDockWidgetArea,pd);
    connect(tree_,&QTreeWidget::itemSelectionChanged,this,[this]{auto items=tree_->selectedItems();if(!items.empty()&&items.front()->data(0,roleKind).isValid())selectObject(static_cast<Kind>(items.front()->data(0,roleKind).toInt()),items.front()->data(0,roleId).toULongLong());});
    connect(viewport_,&InfraViewport::selected,this,[this](InfraViewport::Kind k,std::uint64_t id){selectObject(static_cast<Kind>(k),id);});
}

void InfraMainWindow::buildMenus(){auto* f=menuBar()->addMenu(tr("&File"));auto* n=f->addAction(tr("&New"));n->setShortcut(QKeySequence::New);auto* o=f->addAction(tr("&Open…"));o->setShortcut(QKeySequence::Open);saveAction_=f->addAction(tr("&Save"));saveAction_->setShortcut(QKeySequence::Save);auto* sa=f->addAction(tr("Save &As…"));auto* ex=f->addAction(tr("Export GeoJSON…"));connect(n,&QAction::triggered,this,&InfraMainWindow::newDocument);connect(o,&QAction::triggered,this,&InfraMainWindow::openInteractive);connect(saveAction_,&QAction::triggered,this,&InfraMainWindow::saveCurrent);connect(sa,&QAction::triggered,this,&InfraMainWindow::saveAs);connect(ex,&QAction::triggered,this,&InfraMainWindow::exportInteractive);auto* e=menuBar()->addMenu(tr("&Edit"));undoAction_=e->addAction(tr("Undo"));undoAction_->setShortcut(QKeySequence::Undo);redoAction_=e->addAction(tr("Redo"));redoAction_->setShortcut(QKeySequence::Redo);connect(undoAction_,&QAction::triggered,this,&InfraMainWindow::undo);connect(redoAction_,&QAction::triggered,this,&InfraMainWindow::redo);auto* c=menuBar()->addMenu(tr("&Create"));auto* t=c->addAction(tr("Procedural Terrain"));auto* r=c->addAction(tr("Component Road"));auto* b=c->addAction(tr("Bridge"));auto* u=c->addAction(tr("City Building"));connect(t,&QAction::triggered,this,&InfraMainWindow::createTerrain);connect(r,&QAction::triggered,this,&InfraMainWindow::createRoad);connect(b,&QAction::triggered,this,&InfraMainWindow::createBridge);connect(u,&QAction::triggered,this,&InfraMainWindow::createBuilding);auto* tb=addToolBar(tr("Conceptual Design"));tb->addAction(t);tb->addAction(r);tb->addAction(b);tb->addAction(u);tb->addSeparator();tb->addAction(undoAction_);tb->addAction(redoAction_);}

void InfraMainWindow::newDocument(){if(!confirmDiscard())return;document_={};document_.setName("Regional Concept");document_.clearHistory();path_.clear();dirty_=false;kind_=Kind::None;id_=0;viewport_->setDocument(&document_);rebuildTree();showSelection();changed();dirty_=false;setWindowTitle(tr("%1 — MyDesk Infra").arg(QString::fromStdString(document_.name())));saveAction_->setEnabled(true);}
void InfraMainWindow::createTerrain(){std::vector<double> z;constexpr std::size_t size=21;z.reserve(size*size);for(std::size_t r=0;r<size;++r)for(std::size_t c=0;c<size;++c)z.push_back(100.0+8.0*std::sin(static_cast<double>(c)*0.3)+5.0*std::cos(static_cast<double>(r)*0.35));document_.setDemGrid(0,0,10,size,size,std::move(z));changed();rebuildTree();selectObject(Kind::Terrain,0);viewport_->fitModel();}
void InfraMainWindow::createRoad(){if(document_.dem().cols<2){error(tr("Create terrain before a component road."));return;}const auto& d=document_.dem();double n=d.originNorthing+static_cast<double>(d.rows-1)*d.cellSizeMeters*0.5;double e0=d.originEasting+10,e1=d.originEasting+static_cast<double>(d.cols-2)*d.cellSizeMeters;double z0=document_.terrainElevationAt(e0,n).value_or(100),z1=document_.terrainElevationAt(e1,n).value_or(100);auto id=document_.addRoad("Primary Corridor",4,3.5,80,{{e0,n,z0-1},{(e0+e1)/2,n+20,(z0+z1)/2},{e1,n,z1+1}});changed();rebuildTree();selectObject(Kind::Road,id);viewport_->fitModel();}
void InfraMainWindow::createBridge(){if(document_.roads().empty()){error(tr("Create a road before a bridge."));return;}const auto& r=document_.roads().front();double length=r.totalLengthMeters();auto id=document_.addBridge("Valley Crossing",r.id,length*0.3,length*0.7,4);changed();rebuildTree();selectObject(Kind::Bridge,id);}
void InfraMainWindow::createBuilding(){if(document_.dem().cols<2){error(tr("Create terrain before a building."));return;}const auto& d=document_.dem();double e=d.originEasting+static_cast<double>(d.cols)*d.cellSizeMeters*0.25,n=d.originNorthing+static_cast<double>(d.rows)*d.cellSizeMeters*0.25;auto id=document_.addBuilding("Civic Center","Civic",24,{{e,n},{e+24,n},{e+24,n+18},{e,n+18}});changed();rebuildTree();selectObject(Kind::Building,id);}

void InfraMainWindow::rebuildTree(){tree_->clear();auto root=[this](QString name){auto* i=new QTreeWidgetItem(tree_,{name});i->setExpanded(true);return i;};auto* t=root(tr("Terrain & Context"));auto* ti=new QTreeWidgetItem(t,{tr("DEM Surface"),tr("%1 × %2").arg(document_.dem().cols).arg(document_.dem().rows)});ti->setData(0,roleKind,static_cast<int>(Kind::Terrain));ti->setData(0,roleId,0);auto* rr=root(tr("Component Roads (%1)").arg(document_.roads().size()));for(const auto& r:document_.roads()){auto* i=new QTreeWidgetItem(rr,{QString::fromStdString(r.name),tr("%1 km").arg(r.totalLengthMeters()/1000,0,'f',2)});i->setData(0,roleKind,static_cast<int>(Kind::Road));i->setData(0,roleId,QVariant::fromValue<qulonglong>(r.id));}auto* br=root(tr("Bridges (%1)").arg(document_.bridges().size()));for(const auto& b:document_.bridges()){auto* i=new QTreeWidgetItem(br,{QString::fromStdString(b.name),tr("%1 piers").arg(b.pierCount)});i->setData(0,roleKind,static_cast<int>(Kind::Bridge));i->setData(0,roleId,QVariant::fromValue<qulonglong>(b.id));}auto* bu=root(tr("City Buildings (%1)").arg(document_.buildings().size()));for(const auto& b:document_.buildings()){auto* i=new QTreeWidgetItem(bu,{QString::fromStdString(b.name),QString::fromStdString(b.usageCategory)});i->setData(0,roleKind,static_cast<int>(Kind::Building));i->setData(0,roleId,QVariant::fromValue<qulonglong>(b.id));}}
void InfraMainWindow::selectObject(Kind kind,std::uint64_t id){kind_=kind;id_=id;viewport_->setSelection(static_cast<InfraViewport::Kind>(std::min(static_cast<int>(kind),3)),id);showSelection();}
void InfraMainWindow::showSelection(){stack_->setCurrentIndex(static_cast<int>(kind_));if(kind_==Kind::Road)if(const auto* r=document_.findRoad(id_)){summary_->setText(tr("Component Road: %1").arg(QString::fromStdString(r->name)));roadName_->setText(QString::fromStdString(r->name));roadLanes_->setValue(r->numLanes);roadWidth_->setValue(r->laneWidthMeters);roadSpeed_->setValue(r->designSpeedKmh);roadInfo_->setText(tr("%1 vertices • %2 m 3D length").arg(r->centerline.size()).arg(r->totalLengthMeters(),0,'f',2));}if(kind_==Kind::Bridge)if(const auto* b=document_.findBridge(id_)){summary_->setText(tr("Bridge: %1").arg(QString::fromStdString(b->name)));bridgeName_->setText(QString::fromStdString(b->name));bridgeStart_->setValue(b->startStation);bridgeEnd_->setValue(b->endStation);bridgePiers_->setValue(b->pierCount);bridgeThickness_->setValue(b->deckThicknessMeters);}if(kind_==Kind::Building)if(const auto* b=document_.findBuilding(id_)){summary_->setText(tr("City Building: %1").arg(QString::fromStdString(b->name)));buildingName_->setText(QString::fromStdString(b->name));buildingUsage_->setCurrentText(QString::fromStdString(b->usageCategory));buildingHeight_->setValue(b->roofHeightMeters);buildingInfo_->setText(tr("%1 footprint vertices • base Z %2 m").arg(b->footprint.size()).arg(b->baseElevation,0,'f',2));}if(kind_==Kind::Terrain){summary_->setText(tr("Terrain and project context"));projectName_->setText(QString::fromStdString(document_.name()));crs_->setText(QString::fromStdString(document_.crs()));terrainInfo_->setText(tr("%1 × %2 samples • %3 m cells").arg(document_.dem().cols).arg(document_.dem().rows).arg(document_.dem().cellSizeMeters));}if(kind_==Kind::None)summary_->setText(tr("No infrastructure feature selected"));}
void InfraMainWindow::applyProperties(){bool ok=false;if(kind_==Kind::Road)ok=document_.updateRoad(id_,roadName_->text().toStdString(),roadLanes_->value(),roadWidth_->value(),roadSpeed_->value());else if(kind_==Kind::Bridge)ok=document_.updateBridge(id_,bridgeName_->text().toStdString(),bridgeStart_->value(),bridgeEnd_->value(),bridgePiers_->value(),bridgeThickness_->value());else if(kind_==Kind::Building)ok=document_.updateBuilding(id_,buildingName_->text().toStdString(),buildingUsage_->currentText().toStdString(),buildingHeight_->value());else if(kind_==Kind::Terrain){document_.setName(projectName_->text().toStdString());document_.setCrs(crs_->text().toStdString());ok=true;}if(ok){changed();rebuildTree();showSelection();viewport_->update();}}
void InfraMainWindow::analyzeEarthworks(){auto report=document_.analyzeRoadEarthworks(id_,analysisInterval_->value());if(!report){earthwork_->setText(tr("Analysis unavailable: verify terrain coverage."));return;}earthwork_->setText(tr("Cut %1 m³ • Fill %2 m³ • Max grade %3% • %4 stations").arg(report->cutVolumeCubicMeters,0,'f',1).arg(report->fillVolumeCubicMeters,0,'f',1).arg(report->maximumGradePercent,0,'f',2).arg(report->samples.size()));}
void InfraMainWindow::undo(){if(document_.undo()){changed();kind_=Kind::None;viewport_->setDocument(&document_);rebuildTree();showSelection();}}void InfraMainWindow::redo(){if(document_.redo()){changed();kind_=Kind::None;viewport_->setDocument(&document_);rebuildTree();showSelection();}}
void InfraMainWindow::changed(){dirty_=true;undoAction_->setEnabled(document_.canUndo());redoAction_->setEnabled(document_.canRedo());saveAction_->setEnabled(true);setWindowTitle(tr("%1%2 — MyDesk Infra").arg(QString::fromStdString(document_.name()),dirty_?"*":""));}
bool InfraMainWindow::openDocument(const QString& p){std::string err;auto d=mydesk::infra::InfraDocument::loadNativeFile(p.toStdString(),&err);if(!d){error(QString::fromStdString(err));return false;}document_=std::move(*d);path_=QFileInfo(p).absoluteFilePath();dirty_=false;kind_=Kind::None;viewport_->setDocument(&document_);rebuildTree();showSelection();changed();dirty_=false;setWindowTitle(tr("%1 — MyDesk Infra").arg(QString::fromStdString(document_.name())));return true;}
bool InfraMainWindow::saveDocument(const QString& p){std::string err;if(!document_.saveNativeFile(p.toStdString(),&err)){error(QString::fromStdString(err));return false;}path_=QFileInfo(p).absoluteFilePath();dirty_=false;changed();dirty_=false;setWindowTitle(tr("%1 — MyDesk Infra").arg(QString::fromStdString(document_.name())));return true;}
bool InfraMainWindow::exportGeoJson(const QString& p)const{QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)){error(f.errorString());return false;}auto data=document_.exportGeoJson();return f.write(data.data(),static_cast<qint64>(data.size()))==static_cast<qint64>(data.size());}
bool InfraMainWindow::confirmDiscard(){if(!dirty_)return true;auto a=QMessageBox::question(this,tr("Unsaved project"),tr("Save changes?"),QMessageBox::Save|QMessageBox::Discard|QMessageBox::Cancel);return a==QMessageBox::Discard||(a==QMessageBox::Save&&saveCurrent());}bool InfraMainWindow::saveCurrent(){return path_.isEmpty()?saveAs():saveDocument(path_);}bool InfraMainWindow::saveAs(){auto p=QFileDialog::getSaveFileName(this,tr("Save Infrastructure Model"),path_,tr("MyDesk Infra (*.myinfra)"));if(p.isEmpty())return false;if(!p.endsWith(".myinfra"))p+=".myinfra";return saveDocument(p);}void InfraMainWindow::openInteractive(){if(!confirmDiscard())return;auto p=QFileDialog::getOpenFileName(this,tr("Open Infrastructure Model"),{},tr("MyDesk Infra (*.myinfra)"));if(!p.isEmpty())openDocument(p);}void InfraMainWindow::exportInteractive(){auto p=QFileDialog::getSaveFileName(this,tr("Export GeoJSON"),{},tr("GeoJSON (*.geojson)"));if(!p.isEmpty()){if(!p.endsWith(".geojson"))p+=".geojson";exportGeoJson(p);}}void InfraMainWindow::error(const QString& m)const{QMessageBox::critical(const_cast<InfraMainWindow*>(this),tr("MyDesk Infra"),m);}void InfraMainWindow::closeEvent(QCloseEvent* e){if(!confirmDiscard()){e->ignore();return;}QSettings s;s.setValue("infra/geometry",saveGeometry());s.setValue("infra/state",saveState());e->accept();}
